#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const repoRoot = path.resolve(__dirname, "..");
const runtimeDir = path.join(repoRoot, "nelisp_runtime");
const buildDir = path.join(repoRoot, "build");
const emacsHome = path.join(buildDir, "emacs-home");
const compileLogPath = path.join(buildDir, "play-byte-compile.log");
const loaderPath = path.join(buildDir, "play-bundle-loader.el");
const namesPath = path.join(buildDir, "nelisp-conditional-runtime-names.txt");

const runtimeFiles = [
  "game-runner.el",
  "gamedata-simple.el",
  "gamedata-conditional.el",
  "gamedata-state.el",
  "sumi-json.el",
  "play.el",
];

main();

function main() {
  fs.mkdirSync(buildDir, { recursive: true });
  fs.mkdirSync(emacsHome, { recursive: true });

  run("node", ["tools/statediff_to_elisp.mjs", "nelisp_runtime/gamedata-simple.el"]);
  run("node", [
    "tools/generate_nelisp_conditional_runtime.js",
    "--names-file",
    path.relative(repoRoot, namesPath),
  ]);

  const compile = run(
    "emacs",
    [
      "-Q",
      "--batch",
      "--eval",
      "(setq byte-compile-error-on-warn nil)",
      "-f",
      "batch-byte-compile",
      ...runtimeFiles.map((file) => path.join("nelisp_runtime", file)),
    ],
    { HOME: emacsHome }
  );
  fs.writeFileSync(
    compileLogPath,
    [compile.stdout, compile.stderr].filter(Boolean).join("\n"),
    "utf8"
  );

  fs.writeFileSync(loaderPath, makeLoader(), "utf8");

  const namesCount = fs.readFileSync(namesPath, "utf8").split(/\s+/).filter(Boolean).length;
  console.log(JSON.stringify({
    loader: path.relative(repoRoot, loaderPath).replace(/\\/g, "/"),
    compileLog: path.relative(repoRoot, compileLogPath).replace(/\\/g, "/"),
    conditionalNames: namesCount,
    compiled: runtimeFiles,
  }, null, 2));
}

function run(command, args, extraEnv = {}) {
  const result = spawnSync(command, args, {
    cwd: repoRoot,
    encoding: "utf8",
    env: { ...process.env, ...extraEnv },
  });
  if (result.status !== 0) {
    const detail = [result.stdout, result.stderr].filter(Boolean).join("\n");
    throw new Error(`${command} ${args.join(" ")} failed\n${detail}`);
  }
  return result;
}

function makeLoader() {
  const loads = runtimeFiles
    .map((file) => {
      const base = path.join(runtimeDir, file).replace(/\\/g, "/").replace(/\.el$/, "");
      return `(load "${base}" nil t)`;
    })
    .join("\n");
  return [
    ';;; play-bundle-loader.el --- load compiled play runtime -*- coding: utf-8; lexical-binding: t; -*-',
    ';; Generated by tools/build_play_bundle.js. Prefer .elc when present.',
    loads,
    "",
  ].join("\n");
}
